var mandatoryTriggered = false;
var tempLength = 0;
//var matDates = [];
tw.local.invalidTabs = [];
tw.system.coachValidation.clearValidationErrors();
var validateDec14 = "accepts 14 digits before the decimal point and 2 digits after it.";
//tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.recreateContract
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//debugger;
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
if (tw.local.odcRequest.stepLog.comment != null && tw.local.odcRequest.stepLog.comment != "") {
	maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", " Comment :" + "Shouldn't be more than 500 character");
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals && tw.local.odcRequest.complianceApproval == false) {
	tw.local.odcRequest.stepLog.action = "";
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.stepLog.action", tw.resource.ValidationMessages.MandatoryFields);
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) mandatory(tw.local.odcRequest.exeHubMkrComment, "tw.local.odcRequest.exeHubMkrComment");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator ) {
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason", 80, "Shouldn't be more than 80 characters", "Return reason :- This field shouldn't be more than 80 character");
}
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest) {
	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");
	maxLength(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason", 80, "Shouldn't be more than 80 characters", "Termination reason :- This field shouldn't be more than 80 character");
}
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.createContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.amendContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.recreateContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) {
	//-------------------------------------------------Attachment----------------------------
	if (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create) {
		var selectedAttached = tw.local.odcRequest.attachmentDetails.attachment.listAllSelectedIndices;
		if (selectedAttached.length == 0 || selectedAttached.includes(0) == false) {
			addError("tw.local.odcRequest.attachmentDetails.attachment[0].name", "Customer Request is mandatory to be checked");
		}
	}

	////-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
	mandatory(tw.local.odcRequest.BasicDetails.exportPurpose.name, "tw.local.odcRequest.BasicDetails.exportPurpose");
	mandatory(tw.local.odcRequest.BasicDetails.paymentTerms.name, "tw.local.odcRequest.BasicDetails.paymentTerms");
	mandatory(tw.local.odcRequest.BasicDetails.productCategory.name, "tw.local.odcRequest.BasicDetails.productCategory");
	mandatory(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription");
	mandatory(tw.local.odcRequest.BasicDetails.CountryOfOrigin.name, "tw.local.odcRequest.BasicDetails.CountryOfOrigin.value");
	mandatory(tw.local.odcRequest.BasicDetails.operationType.value, "tw.local.odcRequest.BasicDetails.operationType");
	//add mess 160 to local file
	maxLength(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription", 160, "Shouldn't be more than 160 character", "Commodity Description: " + "Shouldn't be more than 160 character");

	if (tw.local.odcRequest.BasicDetails.Invoice.length == 0) {
		//		tw.local.errorMessage += "<li>" + "Fill in at least one entry in invoices" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.invoiceBillExist", "Fill in at least one entry in invoices");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceDate");
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo");
			maxLength(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo", 20, "Shouldn't be more than 20 character", "invoice Number: " + "Shouldn't be more than 20 character");
		}
	}
	tw.local.invoiceBillExist;
	if (tw.local.odcRequest.BasicDetails.Bills.length == 0) {
		//		tw.local.errorMessage += "<li>" + "Fill in at least one entry in Bills" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.invoiceBillExist", "Fill in at least one entry in Bills");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingDate");
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef");
			maxLength(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef", 20, "Shouldn't be more than 20 character", "Bill Of lading Ref : " + "Shouldn't be more than 20 character");
		}
	}

	if (tw.local.billsExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Bills", "This Bills Number already exist before for the same CIF number");
		}
	}
	if (tw.local.InvoiceExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Invoice", "This Invoive Number already exist before for the same CIF number");
		}
	}
	validateTab(0, "Basic Details Tab");

	//-------------------------------------------------DOCUMENT GENERATION INFO VALIDATION -----------------------------------------
	var needRegenerate = (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate) && tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetter == true;

	var newRequest = tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create;

	if (needRegenerate) {
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value, "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption");
	}

	if (needRegenerate || newRequest) {
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName");
		mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress, "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress");

		if (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms[" + 0 + "]", "Fill in at least one entry in delivery terms or delivery terms extra");
		} else {
			for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length; i++) {
				mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[" + i + "]");
			}
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.Instructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.Instructions[" + 0 + "].value", "Fill in at least one entry in instructions or instructions extra");
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions[" + 0 + "].value", "Fill in at least one entry in payment Instructions or payment instructions extra");
		}
		if (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions.length == 0 && tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length == 0) {
			addError("tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions[" + 0 + "].value", "Fill in at least one entry in special instructions or special instructions extra");
		}

		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[" + i + "]");
		}
		for (var i = 0; i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length; i++) {
			mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[" + i + "]");
		}
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName", 250, "Shouldn't be more than 250 character", "customer Name: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress, "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress", 400, "Shouldn't be more than 400 character", "customer Address: " + "Shouldn't be more than 400 character");

		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra", 250, "Shouldn't be more than 250 character", "Delivery Terms Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra", 250, "Shouldn't be more than 250 character", "Instructions Extra: " + "Shouldn't be more than 250 character");
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra, "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra", 250, "Shouldn't be more than 250 character", "payment Instructions Extra: " + "Shouldn't be more than 250 character");
