tw.local.actionConditions.requestType = tw.local.odcRequest.requestType.value;

//////////////////////////////////////////////////////////////////////////////////////////////////////////
/*Visibilty Conditions*/
/*Basic Details CV Visibility*/
///////////////////////////////
if(tw.local.odcRequest.requestNature.value == tw.epv.RequestNature.UpdateRequest)
	tw.local.parentRequestNumberVIS = "READONLY";
	
else
	tw.local.parentRequestNumberVIS = "None";
	
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create ||tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment){
	tw.local.contractStageVIS = "READONLY";
}
else{
tw.local.contractStageVIS = "NONE";
}
/*Document Generation Section*/
///////////////////////////////
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.requestTypeVIS = "EDITABLE";
}
else{
	tw.local.requestTypeVIS = "NONE";	
}
/*Importer Details Visibility*/
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.bankRefVIS = "EDITABLE";
}
else{
	tw.local.bankRefVIS = "NONE";	
}
if(tw.local.odcRequest.BasicDetails.paymentTerms.name == "004")
{
	tw.local.multiTenorVIS = "Editable";
}
else
{
	tw.local.multiTenorVIS = "None";
}


if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.flexcubeContractnoVis = "EDITABLE";
}
else{
	tw.local.flexcubeContractnoVis = "Readonly";	
}


/*Add remaining conditions based on the request type*/
if(tw.local.odcRequest.BasicDetails.contractStage == "Final")
{
	tw.local.event = "INIT";
}

tw.local.odcRequest.complianceApproval =false;
tw.local.initialAccountList = {};
tw.local.initialAccountList = tw.local.odcRequest.FcCollections.listOfAccounts;

tw.local.invoiceBillExist = 0;


