//}

if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment){

		tw.local.advancedVis = "READONLY";
}
else{

	tw.local.advancedVis = "Editable";
}
tw.local.Createcontract = false;
if(tw.local.odcRequest.BasicDetails.paymentTerms.name=="005"){
	tw.local.odcRequest.ContractCreation.amount = tw.local.odcRequest.FinancialDetailsBR.documentAmount; 
}
else{
	tw.local.odcRequest.ContractCreation.amount = tw.local.odcRequest.FinancialDetailsFO.collectableAmount; 
}"]}},{"targetRef":"2025.7664a7e2-a9ff-4f34-8101-c43dd00b7771","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Generate BarCode","declaredType":"sequenceFlow","id":"2027.7a83b4b5-3b91-4829-8dc8-ced9b3ebb94b","sourceRef":"2025.cf1e1785-71cb-4402-860a-50d18231924b"},{"itemSubjectRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","name":"parentRequestNumberVIS","isCollection":false,"declaredType":"dataObject","id":"2056.69e6eedd-1a2f-4d00-81d3-4be407a38938"},{"itemSubjectRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","name":"x","isCollection":false,"declaredType":"dataObject","id":"2056.d092fe95-e100-4c09-8a3c-ff77d4c19f7f"},{"itemSubjectRef":"itm.12.b0c377d8-c17f-4d70-9ed0-b60db6773a42","name":"drawerAccountsList","isCollection":true,"declaredType":"dataObject","id":"2056.9fea3a16-f7b0-4b82-8b84-e34715aaea53"},{"itemSubjectRef":"itm.12.3fa0d7a0-828a-4d60-99cc-db5ed143fc2d","name":"selectedIndex","isCollection":false,"declaredType":"dataObject","id":"2056.6ca322b0-f3cc-4e23-8c9c-38a72d23c824"},{"itemSubjectRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","name":"fromCurrency","isCollection":false,"declaredType":"dataObject","id":"2056.0c3150de-f48c-4392-8745-78bf480ec637"},{"itemSubjectRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","name":"toCurrency","isCollection":false,"declaredType":"dataObject","id":"2056.c575aebe-5805-45f1-8658-f4b61135671e"},{"itemSubjectRef":"itm.12.536b2aa5-a30f-4eca-87fa-3a28066753ee","name":"rate","isCollection":false,"declaredType":"dataObject","id":"2056.6af17de0-5078-4f22-8c4b-993cf87cace9"},{"outgoing":["2027.c4244b2b-83a7-48e7-84d2-b4067c156976"],"incoming":["2027.de92f3a3-6b57-45da-823d-ab4f833063f4"],"extensionElements":{"postAssignmentScript":["if(!tw.local.isSuccessful || !!tw.local.errorMessage){
