e8-94b251696faf","2027.c37808cb-7c8a-4361-8277-b15bab2ec58b"],"incoming":["2027.e8c836c6-9d1f-4aaa-8f6e-26f53f8a9f5b"],"default":"2027.dfef0443-a57a-4bf3-83e8-94b251696faf","gatewayDirection":"Unspecified","extensionElements":{"nodeVisualInfo":[{"width":32,"x":242,"y":484,"declaredType":"TNodeVisualInfo","height":32}]},"name":"row selected?","declaredType":"exclusiveGateway","id":"2025.91f5b650-2cac-4d93-87d6-0015186e5306"},{"targetRef":"2025.91f5b650-2cac-4d93-87d6-0015186e5306","extensionElements":{"coachEventBinding":[{"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TCoachEventBinding","id":"7f5a9c9f-809f-4b80-88ac-fb8e8236ce74","coachEventPath":"3/Button2"}],"sequenceFlowImplementation":[{"fireValidation":"Never","sboSyncEnabled":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TSequenceFlowImplementation"}],"linkVisualInfo":[{"sourcePortLocation":"bottomLeft","showCoachControlLabel":true,"labelPosition":0.0,"targetPortLocation":"topCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":true,"showLabel":false}]},"name":"To row selected?","declaredType":"sequenceFlow","id":"2027.e8c836c6-9d1f-4aaa-8f6e-26f53f8a9f5b","sourceRef":"2025.38247cc1-4dce-40fc-a547-57a37198b00a"},{"startQuantity":1,"outgoing":["2027.66c1dca2-22f0-4496-83b4-f7ef5b6dd394"],"incoming":["2027.dfef0443-a57a-4bf3-83e8-94b251696faf"],"default":"2027.66c1dca2-22f0-4496-83b4-f7ef5b6dd394","extensionElements":{"nodeVisualInfo":[{"width":95,"x":393,"y":520,"declaredType":"TNodeVisualInfo","height":70}]},"name":"add a row to selected transaction list","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2025.417b30fc-9588-4494-842d-c4018c1ce19b","scriptFormat":"text/x-javascript","script":{"content":["tw.local.collectionCurrencyVis = "READONLY";

var selectedTransactionsIndices = [];
selectedTransactionsIndices = tw.local.odcRequest.FcCollections.retrievedTransactions.listAllSelectedIndices;

function transactionExistsInOtherTable(transaction) {

 if(!!tw.local.odcRequest.FcCollections.selectedTransactions){
 	 for (var k = 0; k < tw.local.odcRequest.FcCollections.selectedTransactions.length; k++) {
 	 if (tw.local.odcRequest.FcCollections.selectedTransactions[k].referenceNumber === transaction.referenceNumber &&
 	tw.local.odcRequest.FcCollections.selectedTransactions[k].postingDate.getDay() == transaction.postingDate.getDay() &&
 	tw.local.odcRequest.FcCollections.selectedTransactions[k].postingDate.getMonth() == transaction.postingDate.getMonth() &&
 	tw.local.odcRequest.FcCollections.selectedTransactions[k].postingDate.getYear() == transaction.postingDate.getYear()) {
 	return true;
 		}
 		}
 	}
 return false;
}



for (var i = 0; i < selectedTransactionsIndices.length; i++) {
 var transactionIndex = selectedTransactionsIndices[i];
 var transaction = tw.local.odcRequest.FcCollections.retrievedTransactions[transactionIndex];

 // Check if the transaction already exists in the other table
 if (!transactionExistsInOtherTable(transaction)) {
 
 transaction.requestID = tw.local.odcRequest.requestID;
 transaction.amountAllocatedForCurrencyRequest = 0;
 transaction.allocatedAmountInRequestCurrency = 0;

 // Add the transaction to selected transactions list
 tw.local.odcRequest.FcCollections.selectedTransactions.push(transaction);
 }
