	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.createContract || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.amendContract ||
	tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) {

	////-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
