//-------------------------------------------------DOCUMENT GENERATION INFO VALIDATION -----------------------------------------	
 tw.local.errorMessage ="";
 var mandatoryTriggered = false;
mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerName , "tw.local.odcRequest.GeneratedDocumentInfo.customerName");
mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress , "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress");
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate)
{ 
	mandatory(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.value , "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption");
}
if(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.length == 0  && tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length == 0){
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[0] , "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra");
	tw.local.errorMessage += "<li>"+"Fill in at least one entry in delivery terms Extra"+"</li>";	
}
else
{
	for(var i=0; i< tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.length ; i++){
		mandatory (tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i] , "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra["+i+"]");
	}
}
if(tw.local.odcRequest.GeneratedDocumentInfo.Instructions.length ==0   && tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length == 0)
{
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[0] , "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra");
	tw.local.errorMessage += "<li>"+"Fill in at least one entry in instructions Extra"+"</li>";
}
if(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.length == 0  && tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length == 0)
{
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[0] , "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra");
	tw.local.errorMessage += "<li>"+"Fill in at least one entry in payment Instructions Extra"+"</li>";
}
if(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructions.length == 0  && tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length == 0)
{
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[0] , "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra");
	tw.local.errorMessage += "<li>"+"Fill in at least one entry in special instructions Extra"+"</li>";
}



for(var i=0; i< tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra.length ; i++){
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra[i] , "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra["+i+"]");
}

for(var i=0; i< tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.length ; i++){
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra[i] , "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra["+i+"]");
}

for(var i=0; i< tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra.length ; i++){
	mandatory (tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra[i] , "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra["+i+"]");
}
maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerName , "tw.local.odcRequest.GeneratedDocumentInfo.customerName", 250 , "Shouldn't be more than 250 character" , "customer Name: " + "Shouldn't be more than 250 character" );
maxLength(tw.local.odcRequest.GeneratedDocumentInfo.customerAddress , "tw.local.odcRequest.GeneratedDocumentInfo.customerAddress", 400 , "Shouldn't be more than 400 character" , "customer Address: " + "Shouldn't be more than 400 character" );


maxLength(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra , "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra", 250 , "Shouldn't be more than 250 character" , "Delivery Terms Extra: " + "Shouldn't be more than 250 character" );
maxLength(tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra , "tw.local.odcRequest.GeneratedDocumentInfo.InstructionsExtra", 250 , "Shouldn't be more than 250 character" , "Instructions Extra: " + "Shouldn't be more than 250 character" );
maxLength(tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra , "tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra", 250 , "Shouldn't be more than 250 character" , "payment Instructions Extra: " + "Shouldn't be more than 250 character" );
maxLength(tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra , "tw.local.odcRequest.GeneratedDocumentInfo.specialInstructionsExtra", 250 , "Shouldn't be more than 250 character" , "Special Instructions Extra: " + "Shouldn't be more than 250 character" );

if(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetter == true )
{
	if(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterOption.name == "003")
	{
		maxLength(tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle , "tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetterTitle", 80 , "Shouldn't be more than 80 character" , "Regenerate RemLetter Title: " + "Shouldn't be more than 80 character" );
	}
}

function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{			
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				if (field < 0)
				{
					var msg= "Invalid Value, This field can not be negative value.";
					addError(fieldName , msg , msg , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
	
			default:
				
				// VALIDATE DATE OBJECT
				if( field && field.getTime && isFinite(field.getTime()) ) {}
				
				else
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;	
				}
		}
	}
	return true;
}
function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}

function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}
function minLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field != null && field != undefined && field.length < len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}

ns16:extensionElements.ns2:postAssignmentScript:
console.group("<<CONTRACT CONTROLLER>>");
console.log("CONTRACT CONTROLLER REQ");
console.log(tw.local.xmlRequest2);
console.log("CONTRACT CONTROLLERRES");
console.log( tw.local.xmlResponse2 );
console.log(tw.local.ResponseInfo2);
console.log("isClosed: ", tw.local.isClosed);
console.groupEnd();

if(tw.local.isSuccessful == false){
	var msg = tw.local.contractStatus || tw.local.serviceName + " Integration Failed";
	var items = tw.local.messageList;
	tw.local.errorPanelVIS = "editable";
	
	if(!!tw.local.errorMsg){
		tw.local.errorMessage = msg + '<br>' + `<ul>${tw.local.errorMsg}</ul>`;
	}
	else if (items && items.length > 0){
		var listItems = items.map(item => `<li>${item}</li>`).join('');
		tw.local.errorMessage = msg + '<br>' + `<ul>${listItems}</ul>`;
	}else{
		tw.local.errorMessage = msg;	
	}
}else{
//tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate
	if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
		tw.local.odcRequest.BasicDetails.flexCubeContractNo2 = tw.local.contractNum || "";
	}
	if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create){
		tw.local.odcRequest.BasicDetails.flexCubeContractNo = tw.local.contractNum || "";
	}
	tw.local.Createcontract = true;
}

